// Inert source viewer shared by AI review flows. The app supplies authorized bytes.
const safeMime=new Set(['image/png','image/jpeg','image/webp','image/gif','application/pdf']);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountEvidenceViewer(root,{documents,load,openPdf,stale=()=>false}){
 const files=documents.filter(d=>safeMime.has(d.mime));
 let generation=0,drawSequence=0,pdf=null,url=null,task=null,page=1,zoom=1,disposed=false;
 const old=n=>disposed||stale()||n!==generation;
 function release(){task?.cancel();task=null;pdf?.loadingTask.destroy();pdf=null;if(url)URL.revokeObjectURL(url);url=null;}
 root.classList.add('ks-evidence');root.innerHTML=`<h3>Original document</h3><div class="ks-evidence-controls"><label>Source<select data-file>${files.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select></label><button type="button" data-prev aria-label="Previous page">←</button><span data-page></span><button type="button" data-next aria-label="Next page">→</button><label>Zoom<select data-zoom><option value="1">Fit width</option><option value="1.5">150%</option><option value="2">200%</option><option value="3">300%</option><option value="4">400%</option></select></label></div><p role="status" aria-live="polite"></p><div class="ks-evidence-viewport" tabindex="0" aria-label="Original document preview"></div>`;
 if(files.length===1){const label=root.querySelector('[data-file]').parentElement;label.hidden=true;root.querySelector('h3').textContent=files[0].name||'Original document';}
 const viewport=root.querySelector('.ks-evidence-viewport'),status=root.querySelector('[role=status]');
 async function draw(n){const seq=++drawSequence;if(old(n))return;task?.cancel();task=null;root.querySelectorAll('[data-prev],[data-next],[data-page]').forEach(el=>el.hidden=!pdf);root.querySelector('[data-prev]').disabled=!pdf||page<=1;root.querySelector('[data-next]').disabled=!pdf||page>=pdf.numPages;root.querySelector('[data-page]').textContent=pdf?`${page} / ${pdf.numPages}`:'Image';const width=Math.max(240,viewport.clientWidth-24)*zoom;
 if(!pdf){const img=viewport.querySelector('img');if(img)img.style.width=width+'px';return;}
 const source=pdf,requested=page;try{const p=await source.getPage(page);if(old(n)||seq!==drawSequence||source!==pdf||requested!==page)return;const base=p.getViewport({scale:1}),view=p.getViewport({scale:Math.min(width/base.width,3)}),canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);canvas.style.width=width+'px';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`Page ${page} of ${pdf.numPages}. Use the source text or original download for accessible text.`);viewport.replaceChildren(canvas);task=p.render({canvasContext:canvas.getContext('2d'),viewport:view});await task.promise;if(!old(n)&&seq===drawSequence)status.textContent='Compare the source with the proposed values. Nothing is applied automatically.';}catch(e){if(!old(n)&&e.name!=='RenderingCancelledException')status.textContent='This page could not be displayed. Open or download the original.';}}
 async function open(){const n=++generation;release();page=1;viewport.replaceChildren();status.textContent='Loading original…';try{const d=await load(root.querySelector('[data-file]').value);if(old(n))return;if(!d||!safeMime.has(d.mime))throw Error('unsupported');
 if(d.mime==='application/pdf'){if(!openPdf)throw Error('unsupported');const next=await openPdf(d.bytes instanceof Uint8Array?d.bytes:new Uint8Array(d.bytes));if(old(n)){await next.loadingTask.destroy();return;}pdf=next;}
 else{const img=document.createElement('img');img.alt=d.name||'Original label photo';if(d.url){const u=new URL(d.url,location.href);if(!['blob:','https:','http:','data:'].includes(u.protocol)||u.protocol==='data:'&&!/^data:image\/(png|jpeg|webp|gif);/i.test(d.url))throw Error('unsupported');img.src=d.url;}else{url=URL.createObjectURL(new Blob([d.bytes],{type:d.mime}));img.src=url;}img.onerror=()=>{if(!old(n))status.textContent='Image unavailable. Open or download the original.';};viewport.append(img);status.textContent='Compare the source with the proposed values. Nothing is applied automatically.';}
 await draw(n);}catch(_){if(!old(n))status.textContent='Preview unavailable. Open or download the original.';}}
 root.querySelector('[data-file]').onchange=open;root.querySelector('[data-zoom]').onchange=e=>{zoom=Number(e.target.value);draw(generation);};root.querySelector('[data-prev]').onclick=()=>{if(pdf&&page>1){page--;draw(generation);}};root.querySelector('[data-next]').onclick=()=>{if(pdf&&page<pdf.numPages){page++;draw(generation);}};
 let last=0;const resize=typeof ResizeObserver==='undefined'?null:new ResizeObserver(()=>{if(last!==viewport.clientWidth){last=viewport.clientWidth;draw(generation);}});resize?.observe(viewport);
 if(files.length)open();else status.textContent='No previewable source. Open the original attachment or source text.';
 return ()=>{disposed=true;generation++;resize?.disconnect();release();viewport.replaceChildren();};
}
